mapper.select:
SELECT m.member_id, m.subscription_id, m.student_id, m.product_id, m.service_code, m.status, st.student_name, st.center_code, p.product_name, p.price, p.total_count FROM erp_bookstore_subscription_member m JOIN erp_bookstore_product p ON p.product_id = m.product_id LEFT JOIN erp_student st ON st.student_id = m.student_id WHERE m.subscription_id = #{subscriptionId}
AND m.status = #{status}
ORDER BY m.member_id

mapper.update:
UPDATE erp_bookstore_subscription
SET next_billing_on = #{newNextBillingOn}
WHERE subscription_id = #{subscriptionId}
  AND status = 'ACTIVE'
  AND next_billing_on = #{expectedNextBillingOn}

UPDATE erp_bookstore_subscription
SET next_billing_on  = #{retryOn},
    fail_count       = fail_count + 1,
    last_fail_reason = #{reason}
WHERE subscription_id = #{subscriptionId}

UPDATE erp_bookstore_subscription
SET status           = 'PAUSED',
    last_fail_reason = #{reason}
WHERE subscription_id = #{subscriptionId}
  AND status = 'ACTIVE'
